const translations: Record<Language, Translations> = { 'pt-BR': ptBR, 'pt-PT': ptPT, en, es };

export function getTranslations(language: Language): Translations {
  return translations[language];
}

export function weekdayLabel(t: Translations, weekday: number): string {
  return t[`wd${weekday}` as TranslationKey];
}

const COLOR_KEYS: Record<SubjectColor, TranslationKey> = {
  green: 'colorGreen', blue: 'colorBlue', purple: 'colorPurple', red: 'colorRed',
  orange: 'colorOrange', teal: 'colorTeal', pink: 'colorPink', gray: 'colorGray',
};

/** Visible name of a subject colour, shown with every swatch. */
export function colorName(t: Translations, color: SubjectColor): string {
  return t[COLOR_KEYS[color]];
}
